1: /**
2:  * dsh-cost-meter —— 会话内实时成本/未命中提醒（零依赖本地插件）。
3:  *
4:  * 与 dsh-mcp-gateway / dsh-agent-guard 同约束：装在 profile 之外，**不 import @deepseek-ai/***。
5:  *
6:  * 作用：把「60% 窗口收尾 / 每步未命中过高 / 累计等效成本过高」从口头规则变成**运行时自动提醒**。
7:  *   - 监听 `session/event`，从 assistant/message 的 usage 累加 uncached / cacheRead / output；
8:  *   - 每次 `agent/pre-step` 前检查阈值，越过就在本轮 messages 末尾追加一条 notice 提示模型收尾/换会话/别再整读；
9:  *   - 同一阈值只提醒一次（按会话记录），避免每步刷屏。
10:  *
11:  * 等效成本口径：cacheRead×0.1 + uncached + output×4。
12:  * 0.1 与 4 是假设倍率，待按实际计费校准，不是某次会话日志的证据。
13:  * 三键全 0 且没有 cacheReadTokens 的 usage 视为 absent：不进等效成本，只计 absentSteps。
14:  */
15: 
16: import { randomUUID } from "node:crypto";
17: 
18: export const name = "cost-meter";
19: export const inject = [];
20: 
21: /**
22:  * 配置归一化（零依赖，不 export Config 以免被 Cordis 当 schemastery schema 校验）。
23:  */
24: function normalizeConfig(input) {
25:   return {
26:     enabled: input?.enabled ?? true,
27:     sessionEquivBudget: input?.sessionEquivBudget ?? 8_000_000,
28:     // 单步未命中门槛 10k（2026-11-10 由 15k 下调，实测 >15k 时单步 reasoning 已失控）。
29:     perStepUncachedBudget: input?.perStepUncachedBudget ?? 10_000,
30:     // 单步 output 门槛 3k（2026-11-10 bug6369：step 46/49/50 单步 output ~10k，
31:     // 全耗在反复推翻自己的 reasoning 上——缺事实时不该脑内演算）。
32:     perStepOutputBudget: input?.perStepOutputBudget ?? 3_000,
33:     // 纯文本且无工具调用：1500 即疑似自我辩论（有工具的长输出仍走 3k）。
34:     bareReasoningBudget: input?.bareReasoningBudget ?? 1_500,
35:     sessionUncachedBudget: input?.sessionUncachedBudget ?? 3_000_000,
36:     // 比 800 万更早的两档。15 万 ≈ 10 个单步未命中预算，或约两步 65k 级 cache 重读（按 0.1 倍率）。
37:     // 100 万比现有 800 万低一个数量级，避免累计档只在会话末期响一次。
38:     sessionEquivEarly: input?.sessionEquivEarly ?? 150_000,
39:     sessionEquivMid: input?.sessionEquivMid ?? 1_000_000,
40:   };
41: }
42: 
43: // 0.1 / 4：假设倍率，待计费校准。
44: const equivOf = (u) => (u.cacheRead || 0) * 0.1 + (u.uncached || 0) + (u.output || 0) * 4;
45: const fmt = (n) => n >= 1e6 ? (n / 1e6).toFixed(2) + 'M' : n >= 1e3 ? (n / 1e3).toFixed(0) + 'k' : String(Math.round(n));
46: 
47: /**
48:  * 从 assistant/message 的 data.usage 取数。
49:  * 三键全 0 且没有 cacheReadTokens：absent，不当成零成本。
50:  * 带 cacheReadTokens 的显式 0（四键）仍是真实记账。
51:  */
52: /** 能看到 content 才判定；看不到返回 unknown，避免误报。 */
53: export function classifyAssistant(event) {
54:   const d = event?.data ?? event ?? {};
55:   const content = d.content ?? d.message?.content;
56:   if (!Array.isArray(content)) return "unknown";
57:   const tool = content.some((b) => b && (b.type === "tool_use" || b.type === "toolCall" || b.type === "functionCall" || b.type === "tool_call"));
58:   return tool ? "tool" : "text";
59: }
60: 
61: function readUsage(event) {
62:   const d = event?.data ?? event;
63:   const u = d?.usage;
64:   if (!u) return undefined;
65:   const hasCacheRead = Object.prototype.hasOwnProperty.call(u, "cacheReadTokens")
66:     || Object.prototype.hasOwnProperty.call(u, "cacheRead");
67:   const absent = !hasCacheRead
68:     && u.uncachedInputTokens === undefined
69:     && u.inputTokens === 0
70:     && u.outputTokens === 0
71:     && (u.totalTokens === 0 || u.totalTokens === undefined);
72:   if (absent) return { absent: true };
73:   return {
74:     absent: false,
75:     uncached: u.uncachedInputTokens ?? u.inputTokens ?? 0,
76:     cacheRead: u.cacheReadTokens ?? u.cacheRead ?? 0,
77:     output: u.outputTokens ?? 0,
78:   };
79: }
80: 
81: let latestAcc;
82: 
83: /** 测试与排查：最近一次 enabled apply 的会话累计。 */
84: export function inspect(sessionId) {
85:   const a = latestAcc?.get(sessionId);
86:   if (!a) return undefined;
87:   return {
88:     uncached: a.uncached,
89:     cacheRead: a.cacheRead,
90:     output: a.output,
91:     lastOutput: a.lastOutput,
92:     steps: a.steps,
93:     absentSteps: a.absentSteps,
94:     equiv: equivOf(a),
95:     fired: [...a.fired],
96:   };
97: }
98: 
99: /** P3-11：从 pre-step 的 messages 里取 user 文本，判断是否同时含「修改+验证+提交」三要素。 */
100: function hasIntentSignal(messages) {
101:   if (!Array.isArray(messages)) return false;
102:   const text = messages
103:     .filter((m) => m && m.role === "user")
104:     .map((m) => {
105:       const c = m.content;
106:       if (typeof c === "string") return c;
107:       if (Array.isArray(c)) return c.map((b) => (typeof b === "string" ? b : b?.text ?? "")).join("\n");
108:       return "";
109:     })
110:     .join("\n");
111:   return /(修复|实现|修改|新增|开发|重构)/.test(text)
112:     && /(验证|测试|构建|build)/.test(text)
113:     && /(提交|push|推送)/.test(text);
114: }
115: 
116: export function apply(ctx, rawConfig) {
117:   const config = normalizeConfig(rawConfig);
118:   if (!config.enabled) return;
119: 
120:   // sessionId -> { uncached, cacheRead, output, steps, absentSteps, fired:Set }
121:   const acc = new Map();
122:   latestAcc = acc;
123: 
124:   const newAcc = () => ({
125:     uncached: 0, cacheRead: 0, output: 0, steps: 0, absentSteps: 0,
126:     lastUncached: 0, lastOutput: 0, lastBare: false, bareCount: 0, bigMissStreak: 0,
127:     committed: false, optimized: false, closing: false,
128:     todoWritten: false, edited: false, buildRan: false,
129:     fired: new Set(),
130:   });
131: 
132:   ctx.on("session/event", (session, event) => {
133:     if (event?.type !== "assistant/message") return;
134:     const u = readUsage(event);
135:     if (!u) return;
136:     const id = session?.header?.id ?? session?.id;
137:     if (id === undefined) return;
138:     let a = acc.get(id);
139:     if (!a) {
140:       a = newAcc();
141:       acc.set(id, a);
142:     }
143:     if (u.absent) {
144:       a.absentSteps += 1;
145:       return;
146:     }
147:     a.uncached += u.uncached;
148:     a.cacheRead += u.cacheRead;
149:     a.output += u.output;
150:     a.steps += 1;
151:     a.lastUncached = u.uncached;
152:     a.lastOutput = u.output;
153:     a.lastBare = classifyAssistant(event) === "text" && u.output > config.bareReasoningBudget;
154:     // 连续纯推理步计数：只有「保持纯推理」才累加，一旦出现工具调用/正常步就清零。
155:     // 审计 P0：同一 turn 连续 2 个无工具调用步后必须升级为硬性「下一步必须调工具」，
156:     // 而不是每步都发同一句软提示（软提示实测拦不住 3–8k 的反复自我辩论）。
157:     a.bareStreak = a.lastBare ? (a.bareStreak || 0) + 1 : 0;
158:     if (a.lastBare) a.bareCount += 1;
159:     // 连续大未命中：第一次只提醒，第二次起把「提示」改成「下一步必须是取数」。
160:     a.bigMissStreak = u.uncached > config.perStepUncachedBudget ? (a.bigMissStreak || 0) + 1 : 0;
161:   });
162: 
163:   ctx.on("session/event", (session, event) => {
164:     const id = session?.header?.id ?? session?.id;
165:     if (id === undefined) return;
166:     let a = acc.get(id);
167:     if (!a) {
168:       a = newAcc();
169:       acc.set(id, a);
170:     }
171:     const type = String(event?.type ?? "");
172:     const d = event?.data ?? {};
173:     const toolName = d.name ?? d.tool ?? d.toolName ?? "";
174:     const blob = JSON.stringify(d.arguments ?? d.input ?? d.args ?? d.command ?? "");
175:     // P3-11：todo_write 出现即视为已外化阶段。
176:     if (/todo_write/i.test(toolName)) a.todoWritten = true;
177:     // P3-12：出现过 edit/write 类工具（\b 不把 todo_write 里的 write 算进来）。
178:     if (/\b(edit|write|apply_patch|multiedit|create_file|str_replace)\b/i.test(toolName)) a.edited = true;
179:     // P3-12：出现过 build/lint/test 命令（npm/pnpm/yarn 同类）。
180:     if (/\b(?:npm|pnpm|yarn)\b[^\n]*\b(?:build|lint|test)\b/i.test(blob)) a.buildRan = true;
181:     if (/pwsh/i.test(toolName) && /git\s+commit/.test(blob)) a.committed = true;
182:     if (/token-optimizer/.test(blob) || /token-optimizer/.test(toolName)) a.optimized = true;
183:     const reason = d.reason ?? d.status ?? "";
184:     if ((type === "turn/end" || type === "agent/turn-end" || type === "turn/completed") && reason === "completed" && a.committed && !a.optimized) {
185:       a.closing = true;
186:     }
187:   });
188: 
189:   const notice = (text, summary) => ({
190:     // 复刻 createMessage 的最小形状（role + source + 稳定 id），零依赖构造合法 user 消息。
191:     id: randomUUID(),
192:     role: "user",
193:     content: [{ type: "text", text }],
194:     source: { kind: "cost-meter", form: "notice", summary },
195:   });
196: 
197:   ctx.on("agent/pre-step", ({ agent, messages }, next) => {
198:     const id = agent?.session?.header?.id ?? agent?.session?.id;
199:     if (id === undefined) return next();
200:     let a = acc.get(id);
201:     if (!a) {
202:       a = newAcc();
203:       acc.set(id, a);
204:     }
205: 
206:     const equiv = equivOf(a);
207:     const intentHit = !a.todoWritten && hasIntentSignal(messages);
208:     // 本 turn 早先已有过无工具超长步，才给带工具的超预算步加上“下一步必须调工具”。
209:     const priorBare = a.bareCount > (a.lastBare ? 1 : 0);
210:     const overOutput = a.lastOutput > config.perStepOutputBudget;
211:     const outputText = priorBare
212:       ? `[cost-meter] 上一步已超预算，output ${fmt(a.lastOutput)} tokens（>${fmt(config.perStepOutputBudget)}）。下一步第一件事必须是工具调用，禁止再并列 Option 1/2/3。`
213:       : `[cost-meter] 上一步 output ${fmt(a.lastOutput)} tokens（>${fmt(config.perStepOutputBudget)}）。`;
214:     const checks = [
215:       ["perStep", a.lastUncached > config.perStepUncachedBudget && a.bigMissStreak < 2,
216:         `[cost-meter] 上一步未命中 ${fmt(a.lastUncached)} tokens（>${fmt(config.perStepUncachedBudget)}），极高。典型成因按概率排序：① 全仓/容器级 grep——缩到 src/views/<模块> 再搜；② 缺真实值在脑内演算——先查一条 SQL / 一个接口返回；③ 大文件整读——grep 定位后 read offset/limit。先判断自己属于哪种，再动下一步。`],
217:       ["perStepLookup", a.bigMissStreak >= 2,
218:         `[cost-meter] 连续 ${a.bigMissStreak} 步未命中 >${fmt(config.perStepUncachedBudget)}，提醒没改掉走势。下一步第一件事必须是一次取数，且只允许以下三种之一：① 带 offset/limit 的窄读 ② 带 path+include 的 grep ③ 一条 SQL（先 ALL_TAB_COLUMNS / 一行样本）。禁止整读、禁止全仓/容器级 grep、禁止推演。`],
219:       ["perStepOutput", overOutput && !priorBare, outputText],
220:       ["perStepOutputAfterA", overOutput && priorBare, outputText],
221:       ["bareReasoning", a.lastBare && a.bareStreak < 2,
222:         `[reasoning-watchdog] 上一步输出 ${fmt(a.lastOutput)} tokens 且无工具调用，疑似自我辩论。停止推演：调一次工具取事实，或直接下结论。`],
223:       // 审计 P0：连续第 2 个纯推理步起升级为硬指令。插件层无法真正下调 reasoningEffort
224:       // （reasoningEffort 在 turn 开始时已固定，pre-step 只能在 enter/reject 间选），
225:       // 所以这里用「下一步第一件事必须是工具调用」把空转截断在行为层。
226:       ["bareReasoningEscalate", a.lastBare && a.bareStreak >= 2,
227:         `[reasoning-watchdog] 已连续 ${a.bareStreak} 步无工具调用（每步 >${fmt(config.bareReasoningBudget)} tokens，当前 ${fmt(a.lastOutput)}）。这是「推理代替取数」的硬信号：下一步第一件事必须是工具调用——查一条数据 / 一次窄读 / 一次 grep 定位。禁止再列 Option 1/2/3，禁止再自我辩论；若确实无法推进就直接下结论收尾。`],
228:       ["closingCheck", a.closing,
229:         `[closing-check] 收尾证据不齐：本轮有提交，但未见构建/测试记录、也未见 token-optimizer 记录。构建/部署/回写证据不齐不要收尾——用 ask_user_question 明确是否继续排查。`],
230:       ["intentTodo", intentHit,
231:         `[todo-gate] 本任务含「修改+验证+提交」，先用 todo_write 把阶段外化，再动手。`],
232:       ["buildBaseline", a.edited && !a.buildRan,
233:         `[build-gate] 已开始改文件但本会话未见构建/测试基线。先跑一次 npm run build（或读最近 CI 结果），区分「预存在编译错误」与本次改动。`],
234:       ["sessionUncached", a.uncached > config.sessionUncachedBudget,
235:         `[cost-meter] 本会话累计未命中 ${fmt(a.uncached)} tokens（>${fmt(config.sessionUncachedBudget)}）。成本已高，收窄任务范围、避免重复整读，必要时开新会话。`],
236:       ["sessionEquivEarly", equiv > config.sessionEquivEarly,
237:         `[cost-meter] 本会话等效成本 ${fmt(equiv)}（>${fmt(config.sessionEquivEarly)}，含 cache 重读；另有 ${a.absentSteps} 步没有用量）。先收窄读取，别等单步未命中才停。`],
238:       ["sessionEquivMid", equiv > config.sessionEquivMid,
239:         `[cost-meter] 本会话等效成本 ${fmt(equiv)}（>${fmt(config.sessionEquivMid)}）。已明显高于单步预算，准备收尾或换会话。`],
240:       ["sessionEquiv", equiv > config.sessionEquivBudget,
241:         `[cost-meter] 本会话等效成本 ${fmt(equiv)}（>${fmt(config.sessionEquivBudget)}，含 ${a.steps} 步）。接近收尾线：尽快给出结论或拆分到新会话，别用 compaction 硬撑。`],
242:     ];
243:     // 只看上一步的规则：每步都可能再超，不能被会话级 fired 吞掉。
244:     const repeatable = new Set(["perStepOutput", "perStepOutputAfterA", "bareReasoning", "bareReasoningEscalate", "perStepLookup"]);
245:     const extra = [];
246:     for (const [key, hit, text] of checks) {
247:       if (!hit) continue;
248:       if (!repeatable.has(key) && a.fired.has(key)) continue;
249:       a.fired.add(key);
250:       extra.push(notice(text, `cost-meter ${key}`));
251:     }
252:     if (extra.length === 0) return next();
253:     return next().then((decision) => {
254:       if (decision?.kind && decision.kind !== "enter") return decision;
255:       const base = decision?.messages ?? messages ?? [];
256:       return { ...(decision ?? {}), kind: "enter", messages: [...base, ...extra] };
257:     });
258:   });
259: }

