1: // cost-meter 自测：验证 usage 累加、阈值触发一次、注入到 messages。
2: import assert from 'assert';
3: import fs from 'fs';
4: import { apply, inspect, name } from './lib/index.js';
5: 
6: assert.equal(name, 'cost-meter');
7: 
8: // 收集事件处理器
9: const sessionHandlers = [];
10: let onPreStep;
11: const ctx = {
12:   on(evt, h) {
13:     if (evt === 'session/event') sessionHandlers.push(h);
14:     if (evt === 'agent/pre-step') onPreStep = h;
15:   },
16: };
17: const onSession = (session, event) => { for (const h of sessionHandlers) h(session, event); };
18: apply(ctx, { enabled: true, perStepUncachedBudget: 1000, sessionUncachedBudget: 100000, sessionEquivBudget: 100000000 });
19: 
20: const session = { header: { id: 's1' } };
21: const agent = { session };
22: 
23: // 模拟两次 assistant/message：一次大未命中
24: onSession(session, { type: 'assistant/message', data: { usage: { uncachedInputTokens: 5000, cacheReadTokens: 1000, outputTokens: 200 } } });
25: onSession(session, { type: 'assistant/message', data: { usage: { uncachedInputTokens: 500, cacheReadTokens: 800, outputTokens: 100 } } });
26: 
27: // pre-step：应触发 perStep（最后一步 uncached 500 < 1000 不触发，但上一步 5000 是最后写入的值）
28: // 注意 lastUncached 被第二次覆盖成 500，所以 perStep 不触发；先验证不触发
29: let out = await onPreStep({ agent, messages: [] }, async () => ({ kind: 'enter', messages: [] }));
30: assert.equal(out.messages.length, 0, 'no notice when below per-step');
31: 
32: // 再发一次大未命中，使 lastUncached=12000
33: onSession(session, { type: 'assistant/message', data: { usage: { uncachedInputTokens: 12000, cacheReadTokens: 0, outputTokens: 0 } } });
34: out = await onPreStep({ agent, messages: [] }, async () => ({ kind: 'enter', messages: [] }));
35: assert.equal(out.messages.length, 1, 'perStep notice injected');
36: assert.ok(out.messages[0].content[0].text.includes('cost-meter'));
37: assert.ok(out.messages[0].content[0].text.includes('未命中'));
38: 
39: // 同一阈值不再重复提醒
40: out = await onPreStep({ agent, messages: [] }, async () => ({ kind: 'enter', messages: [] }));
41: assert.equal(out.messages.length, 0, 'perStep fires once');
42: 
43: // 累计未命中超过 sessionUncachedBudget(100000)? 当前累计 5000+500+12000=17500 < 100000 不触发
44: assert.equal(out.messages.length, 0);
45: 
46: // disabled: 不注册
47: let reg = false; const ctx2 = { on() { reg = true; } };
48: apply(ctx2, { enabled: false });
49: assert.equal(reg, false);
50: 
51: // 规则 A/B 不依赖夹具。用独立 ctx，避免和上面的累计会话混在一起。
52: const ruleHandlers = [];
53: let preRule;
54: const ctxRule = {
55:   on(evt, handler) {
56:     if (evt === 'session/event') ruleHandlers.push(handler);
57:     if (evt === 'agent/pre-step') preRule = handler;
58:   },
59: };
60: apply(ctxRule, { enabled: true });
61: const onRule = (session, event) => { for (const h of ruleHandlers) h(session, event); };
62: const textMsg = (n) => ({ type: 'assistant/message', data: { content: [{ type: 'text', text: 'x' }], usage: { uncachedInputTokens: 1, cacheReadTokens: 0, outputTokens: n } } });
63: const toolMsg = (n) => ({ type: 'assistant/message', data: { content: [{ type: 'tool_use', name: 'pwsh' }], usage: { uncachedInputTokens: 1, cacheReadTokens: 0, outputTokens: n } } });
64: const texts = (res) => (res.messages ?? []).map((m) => m.content[0].text).join('\n');
65: const onlyTool = { header: { id: 'rule-b-tool' } };
66: onRule(onlyTool, toolMsg(4000));
67: let b = await preRule({ agent: { session: onlyTool }, messages: [] }, async () => ({ kind: 'enter', messages: [] }));
68: assert.ok(!texts(b).includes('下一步第一件事'), 'tool-only over-output does not demand a tool');
69: const afterA = { header: { id: 'rule-b-after-a' } };
70: onRule(afterA, textMsg(2000));
71: onRule(afterA, toolMsg(4000));
72: b = await preRule({ agent: { session: afterA }, messages: [] }, async () => ({ kind: 'enter', messages: [] }));
73: assert.ok(texts(b).includes('下一步第一件事必须是工具调用'), 'after rule A, over-output demands a tool');
74: 
75: // 连续两步大未命中：第一次只提醒，第二次起强制取数，且每步都再注入。
76: const streak = { header: { id: 'miss-streak' } };
77: const big = (n) => ({ type: 'assistant/message', data: { usage: { uncachedInputTokens: n, cacheReadTokens: 0, outputTokens: 1 } } });
